 "content": "def transform(grid):
    """Fill gaps between same-color markers that share a row or column."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker_colors = [color for color, _ in counts.most_common() if color != background]
    if not marker_colors:
        return out
    marker = marker_colors[0]
    fill = 3
    h, w = len(grid), len(grid[0])
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if grid[r][c] != marker:
                    out[r][c] = fill
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 2:
            for r in range(min(rows) + 1, max(rows)):
                if grid[r][c] != marker:
                    out[r][c] = fill
    return out

